parameters.jsCode:
const item = $input.first().json;

return [{
  json: {
    model: item.model,
    prompt: item.prompt,
    stream: false,
    format: "json"
  }
}];

const raw = $json.response;

if (!raw) {
  throw new Error('Ollama response is empty');
}

let article;

try {
  article = JSON.parse(raw);
} catch (error) {
  throw new Error('Invalid article JSON: ' + error.message);
}

return {
  json: {
    ...article,
    topic: $('Config').first().json.Topic,
    blogId: $('Config').first().json.blogId
  }
};

// Remembers the title (avoids repeats) and prints a handy edit link.
const sd = $getWorkflowStaticData('global');
const cfg = $('Config').first().json;
const b = $('Build HTML').first().json;
const r = $input.first().json;
sd.titles = [...(sd.titles || []), b.title].slice(-60);
return [{ json: {
  status: r.status || 'DRAFT',
  title: r.title || b.title,
  postId: r.id,
  editUrl: `https://www.blogger.com/blog/post/edit/${cfg.blogId}/${r.id}`,
  labels: b.labels
}}];

const article = $json;

function escapeHtml(value = '') {
  return String(value).replace(/[&<>"']/g, char => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[char]));
}

function codeBlock(code, language = 'text') {
  if (!code) return '';
  return `<pre class="code-block"><code class="language-${escapeHtml(language)}">${escapeHtml(code)}</code></pre>`;
}

function slug(text = '') {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

const sections = (article.sections || []).map((section, i) => {
  const id = slug(section.heading || `section-${i + 1}`);
  return `
    <section class="article-section" id="${id}">
      <h2>${escapeHtml(section.heading || `Section ${i + 1}`)}</h2>
      <p>${escapeHtml(section.content || '').replace(/\n/g, '<br>')}</p>
      ${section.code ? codeBlock(section.code, section.code_language || 'verilog') : ''}
    </section>`;
}).join('');

const figures = (article.figures || []).map((figure, i) => `
  <figure class="technical-figure">
    <div class="figure-placeholder">
      <strong>Figure ${i + 1}: ${escapeHtml(figure.title || 'Technical diagram')}</strong>
      <p>${escapeHtml(figure.description || '')}</p>
      ${figure.diagram_source
        ? `<pre><code>${escapeHtml(figure.diagram_source)}</code></pre>`
        : ''}
      <p><em>${escapeHtml(figure.caption || '')}</em></p>
    </div>
  </figure>
`).join('');

const toc = (article.sections || []).map((section, i) =>
  `<li><a href="#${slug(section.heading || `section-${i + 1}`)}">${escapeHtml(section.heading || `Section ${i + 1}`)}</a></li>`
).join('');

const specialCode = [
  ['Verilog RTL Implementation', article.verilog_rtl],
  ['Verification Testbench', article.testbench]
].filter(([, code]) => code);

const codeSections = specialCode.map(([heading, code]) => `
  <section class="article-section">
    <h2>${escapeHtml(heading)}</h2>
    ${codeBlock(code, 'verilog')}
  </section>
`).join('');

const html = `
<article class="chipworld-article">
<style>
.chipworld-article {
  font-family: Arial, sans-serif;
  color: #243247;
  line-height: 1.8;
  max-width: 900px;
  margin: auto;
}
.chipworld-article h1 {
  color: #12345a;
  line-height: 1.3;
  font-size: 2em;
}
.chipworld-article h2 {
  color: #176b87;
  border-bottom: 2px solid #dce8f0;
  padding-bottom: 8px;
  margin-top: 32px;
}
.chipworld-article .article-intro {
  background: #f0f6fa;
  padding: 18px;
  border-left: 4px solid #176b87;
  border-radius: 6px;
}
.chipworld-article .code-block,
.chipworld-article .figure-placeholder {
  background: #f4f6f8;
  border: 1px solid #d9e1e8;
  border-radius: 8px;
  padding: 16px;
  overflow-x: auto;
}
.chipworld-article .code-block {
  color: #17212f;
  white-space: pre;
  font-family: Consolas, monospace;
  font-size: 14px;
  line-height: 1.5;
}
.chipworld-article a { color: #176b87; }
.chipworld-article figure { margin: 24px 0; }
</style>

<header>
  <h1>${escapeHtml(article.title || article.topic || 'Engineering Article')}</h1>
</header>

<section class="article-intro">
  ${escapeHtml(article.introduction || '').replace(/\n/g, '<br>')}
</section>

<nav class="article-toc">
  <h2>Table of Contents</h2>
  <ol>${toc}</ol>
</nav>

${sections}

${figures ? `<h2>Figures and Diagrams</h2>${figures}` : ''}

${codeSections}

${article.summary ? `
<section class="article-section">
  <h2>Summary</h2>
  <p>${escapeHtml(article.summary).replace(/\n/g, '<br>')}</p>
</section>` : ''}

</article>`;

return {
  json: {
    title: article.title || article.topic || 'Engineering Article',
    blogId: article.blogId,
    html,
    article
  }
};

// Parses the outline JSON (with fallbacks) and emits ONE ITEM PER SECTION, each with its own writing prompt.
const cfg = $('Config').first().json;
const pick = $('Config').first().json;

function parseJson(t) {
  if (typeof t !== 'string') return null;
  const s = t.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}

const plan = parseJson($input.first().json.response) || {};
let sections = (Array.isArray(plan.sections) ? plan.sections : [])
  .filter(s => s && typeof s.heading === 'string' && s.heading.trim())
  .slice(0, 5)
  .map(s => ({
    heading: s.heading.trim().slice(0, 80),
    points: Array.isArray(s.points) ? s.points.map(String) : (s.points ? [String(s.points)] : [])
  }));

let usedFallback = false;
if (sections.length < 3) {
  usedFallback = true;
  sections = [
    { heading: 'The core idea', points: ['What it is', 'Why it matters'] },
    { heading: 'How it works', points: ['Main steps', 'Key terms'] },
    { heading: 'A worked example', points: ['A simple example with small numbers or an analogy'] },
    { heading: 'Uses and common mistakes', points: ['Real-world uses', 'Common misunderstandings'] }
  ];
}

const title = String(plan.title || pick.seed).replace(/["\n]/g, '').slice(0, 90);
const meta = {
  title,
  description: String(plan.description || pick.seed).slice(0, 160),
  keywords: Array.isArray(plan.keywords) ? plan.keywords.map(k => String(k).toLowerCase()).slice(0, 5) : [],
  intro: String(plan.intro || `This post explains: ${pick.seed}.`).slice(0, 600),
  cat: pick.cat, level: pick.level, seed: pick.seed, usedFallback
};

const system = 'You are a STEM educator writing one section of a blog post. Output plain text only.';
return sections.map((s, idx) => ({
  json: {
    ...meta, sectionIndex: idx, total: sections.length, heading: s.heading,
    ollamaRequest: {
      model: cfg.model, system, stream: false, keep_alive: '5m',
      prompt: `Blog title: ${title}
Audience level: ${pick.level}
Write the section titled "${s.heading}".
Cover these points: ${s.points.join('; ') || pick.seed}

Rules:
-Length and structure: Write approximately 200 words, organized into 2–8 short paragraphs separated by a blank line. Keep the explanation focused and avoid unnecessary repetition.

-Technical definitions: Define every important technical term, acronym, or abbreviation the first time it appears. Use the full term before introducing its acronym in parentheses.

-Practical understanding: Include at least one concrete everyday analogy or a small worked example that makes the concept easier to understand. Ensure the analogy accurately reflects the technical concept, and explain where it differs if necessary.

-Accuracy: Use only facts you can confidently support. Never invent statistics, dates, specifications, citations, experiments, or results. If a detail is uncertain, omit it or describe it cautiously.

-Clarity: Use clear, professional English suitable for engineering students and beginners. Explain complex ideas in simple language without sacrificing technical correctness.

-Relevance: Stay focused on the requested topic. Include only details that help the reader understand the concept or apply it.

-Formatting: Use natural paragraphs, correct grammar, and consistent technical notation. Avoid excessive bullet points, decorative symbols, and unexplained code.

-Examples and code: If code is requested, ensure it is syntactically plausible, relevant, and clearly explained. Never claim code has been tested unless it actually has been tested.

-Uncertainty: Distinguish established facts from assumptions. If reliable information is unavailable, state the limitation rather than guessing.

-Output: Return only the requested article or explanation. Do not include commentary about these rules or describe your writing process.
- You may use **bold** for key terms and "- " bullet lines (max 4 bullets).
- Do not write headings, titles, emojis, or a closing summary${idx === sections.length - 1 ? '' : ' or any conclusion'}.
Output only the section text.`,
      options: { temperature: 0.6, num_ctx: 4096, num_predict: 450 }
    }
  }
}));

// Collects the written sections and builds the wrap-up (takeaways, quiz, figure spec) prompt.
const cfg = $('Config').first().json;
const meta = $('Parse Outline').all().map(i => i.json);
const resp = $input.all().map(i => i.json.response || '');
const first = meta[0];

const sections = meta.map((m, i) => ({
  heading: m.heading,
  text: String(resp[i] || '').trim(),
  missing: String(resp[i] || '').trim().length < 150
}));

const headings = sections.map(s => s.heading).join(' | ');
const system = 'You are a STEM educator. Reply with valid JSON only.';
const prompt = `Blog post title: ${first.title}
Category: ${first.cat}
Section headings: ${headings}

Return JSON with exactly these keys:
{
  "takeaways": ["3 to 4 short sentences summarising the main lessons"],
  "quiz": [{"question": "...", "answer": "1 to 2 sentence answer"}],
  "labels": ["2 to 3 short topic labels"],
  "figure": { }
}
Quiz: exactly 3 questions that test understanding, not trivia.
Figure: choose ONE type that best fits the topic and fill it in:
- "flow" for a process or system:
  {"type":"flow","title":"...","caption":"...","steps":["3 to 5 labels, max 4 words each"]}
- "function" for how one quantity changes with another:
  {"type":"function","title":"...","caption":"...","shape":"linear|quadratic|exponential|logarithmic|sine|sigmoid|inverse","x_label":"...","y_label":"..."}
- "bar" for a conceptual comparison:
  {"type":"bar","title":"...","caption":"...","y_label":"...","labels":["3 to 5 items"],"values":[relative scores from 1 to 10]}
Never invent real-world statistics. Bar values are relative and illustrative only.`;

return [{ json: {
  ...first, sections,
  ollamaRequest: {
    model: cfg.model, system, prompt, stream: false, format: 'json', keep_alive: '5m',
    options: { temperature: 0.4, num_ctx: 4096, num_predict: 700 }
  }
}}];

// Parses wrap-up JSON, renders the SVG figure, and builds the final Blogger HTML.
const d = $('Assemble').first().json;
const wrap = $input.first().json.response;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function parseJson(t) {
  if (typeof t !== 'string') return null;
  const s = t.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
const W = 640, H = 360;
const C = { ink: '#1f2937', muted: '#6b7280', accent: '#2563eb', light: '#dbeafe', bg: '#f8fafc', grid: '#e5e7eb' };
const FONT = 'Arial,Helvetica,sans-serif';

// ---------- text -> HTML ----------
const inline = s => esc(s)
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/`([^`]+)`/g, '<code style="background:#f1f5f9;color:#0f172a;padding:1px 5px;border-radius:4px;font-size:0.92em">$1</code>');

function toHtml(text, heading) {
  const cleaned = String(text || '').replace(/\r/g, '').replace(/```[a-z]*/gi, '').replace(/^#+\s.*$/gm, '')
    .split('\n').filter(l => l.trim().toLowerCase() !== String(heading).trim().toLowerCase()).join('\n').trim();
  if (!cleaned) return '<p style="margin:0 0 16px"><em>[TODO: this section was not generated - write it manually.]</em></p>';
  return cleaned.split(/\n\s*\n/).map(b => {
    const lines = b.split('\n').map(l => l.trim()).filter(Boolean);
    if (lines.length && lines.every(l => /^[-*\u2022]\s+/.test(l))) {
      return '<ul style="margin:0 0 16px;padding-left:24px">' +
        lines.map(l => '<li style="margin:4px 0">' + inline(l.replace(/^[-*\u2022]\s+/, '')) + '</li>').join('') + '</ul>';
    }
    return '<p style="margin:0 0 16px">' + inline(lines.join(' ')) + '</p>';
  }).join('\n');
}

// ---------- SVG figures ----------
function wrapText(t, max) {
  const words = String(t).split(/\s+/); const lines = []; let cur = '';
  for (const w of words) {
    if ((cur + ' ' + w).trim().length > max && cur) { lines.push(cur); cur = w; } else { cur = (cur + ' ' + w).trim(); }
  }
  if (cur) lines.push(cur);
  return lines.slice(0, 3);
}
const svgOpen = title =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}" style="width:100%;height:auto;max-width:640px;display:block;margin:0 auto;background:${C.bg};border:1px solid #e2e8f0;border-radius:8px">` +
  `<text x="${W / 2}" y="28" text-anchor="middle" font-family="${FONT}" font-size="18" font-weight="bold" fill="${C.ink}">${esc(title)}</text>`;

function flowSvg(f) {
  const steps = f.steps.slice(0, 5).map(s => String(s).slice(0, 40)); const n = steps.length;
  const gap = 36, bh = 90, bw = (W - 40 - gap * (n - 1)) / n, y = H / 2 - bh / 2 + 10;
  const maxc = Math.max(8, Math.floor(bw / 7.5));
  let s = svgOpen(f.title) +
    `<defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="${C.muted}"/></marker></defs>`;
  steps.forEach((t, i) => {
    const x = 20 + i * (bw + gap);
    s += `<rect x="${x.toFixed(1)}" y="${y}" width="${bw.toFixed(1)}" height="${bh}" rx="10" fill="${C.light}" stroke="${C.accent}" stroke-width="2"/>`;
    s += `<text x="${(x + 10).toFixed(1)}" y="${y + 18}" font-family="${FONT}" font-size="12" font-weight="bold" fill="${C.accent}">${i + 1}</text>`;
    const lines = wrapText(t, maxc);
    lines.forEach((ln, j) => {
      s += `<text x="${(x + bw / 2).toFixed(1)}" y="${(y + bh / 2 + (j - (lines.length - 1) / 2) * 18 + 5).toFixed(1)}" text-anchor="middle" font-family="${FONT}" font-size="14" fill="${C.ink}">${esc(ln)}</text>`;
    });
    if (i < n - 1) s += `<line x1="${(x + bw + 4).toFixed(1)}" y1="${y + bh / 2}" x2="${(x + bw + gap - 4).toFixed(1)}" y2="${y + bh / 2}" stroke="${C.muted}" stroke-width="2" marker-end="url(#arr)"/>`;
  });
  return s + '</svg>';
}

function fnSvg(f) {
  const L = 70, R = 30, T = 50, B = 60, pw = W - L - R, ph = H - T - B;
  const fns = {
    linear: x => x, quadratic: x => x * x, exponential: x => Math.pow(2, x / 2),
    logarithmic: x => Math.log(1 + x), sine: x => Math.sin(x * 0.628),
    sigmoid: x => 1 / (1 + Math.exp(-(x - 5))), inverse: x => 1 / (1 + x)
  };
  const fn = fns[f.shape] || fns.linear;
  const pts = []; for (let i = 0; i <= 60; i++) { const x = i / 6; pts.push([x, fn(x)]); }
  const ys = pts.map(p => p[1]); const mn = Math.min(...ys), mx = Math.max(...ys);
  const path = pts.map((p, i) => {
    const px = L + (p[0] / 10) * pw, py = T + ph - ((p[1] - mn) / ((mx - mn) || 1)) * ph;
    return (i ? 'L' : 'M') + px.toFixed(1) + ',' + py.toFixed(1);
  }).join(' ');
  let s = svgOpen(f.title);
  for (let g = 1; g <= 4; g++) s += `<line x1="${L}" y1="${T + ph * g / 5}" x2="${L + pw}" y2="${T + ph * g / 5}" stroke="${C.grid}"/>`;
  s += `<line x1="${L}" y1="${T}" x2="${L}" y2="${T + ph}" stroke="${C.ink}" stroke-width="2"/>`;
  s += `<line x1="${L}" y1="${T + ph}" x2="${L + pw}" y2="${T + ph}" stroke="${C.ink}" stroke-width="2"/>`;
  s += `<path d="${path}" fill="none" stroke="${C.accent}" stroke-width="3" stroke-linejoin="round"/>`;
  s += `<text x="${L + pw / 2}" y="${H - 18}" text-anchor="middle" font-family="${FONT}" font-size="14" fill="${C.ink}">${esc(f.x_label || 'Input')}</text>`;
  s += `<text transform="rotate(-90)" x="${-(T + ph / 2)}" y="24" text-anchor="middle" font-family="${FONT}" font-size="14" fill="${C.ink}">${esc(f.y_label || 'Output')}</text>`;
  return s + '</svg>';
}

function barSvg(f) {
  const labels = f.labels.slice(0, 6).map(l => String(l).slice(0, 16));
  const vals = f.values.slice(0, labels.length).map(Number);
  const L = 70, R = 20, T = 50, B = 70, pw = W - L - R, ph = H - T - B;
  const max = Math.max(...vals, 1), slot = pw / labels.length, bw = Math.min(70, slot * 0.6);
  let s = svgOpen(f.title);
  s += `<line x1="${L}" y1="${T}" x2="${L}" y2="${T + ph}" stroke="${C.ink}" stroke-width="2"/>`;
  s += `<line x1="${L}" y1="${T + ph}" x2="${L + pw}" y2="${T + ph}" stroke="${C.ink}" stroke-width="2"/>`;
  labels.forEach((lab, i) => {
    const h = (vals[i] / max) * ph, x = L + i * slot + (slot - bw) / 2, y = T + ph - h;
    s += `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw.toFixed(1)}" height="${h.toFixed(1)}" rx="4" fill="${C.accent}"/>`;
    s += `<text x="${(x + bw / 2).toFixed(1)}" y="${(y - 6).toFixed(1)}" text-anchor="middle" font-family="${FONT}" font-size="13" fill="${C.ink}">${vals[i]}</text>`;
    wrapText(lab, 12).forEach((ln, j) => {
      s += `<text x="${(x + bw / 2).toFixed(1)}" y="${T + ph + 20 + j * 15}" text-anchor="middle" font-family="${FONT}" font-size="13" fill="${C.ink}">${esc(ln)}</text>`;
    });
  });
  s += `<text transform="rotate(-90)" x="${-(T + ph / 2)}" y="24" text-anchor="middle" font-family="${FONT}" font-size="14" fill="${C.ink}">${esc(f.y_label || 'Relative score')}</text>`;
  return s + '</svg>';
}

function validFigure(f) {
  if (!f || typeof f !== 'object') return false;
  if (f.type === 'flow') return Array.isArray(f.steps) && f.steps.length >= 2;
  if (f.type === 'function') return typeof f.shape === 'string';
  if (f.type === 'bar') return Array.isArray(f.labels) && Array.isArray(f.values) && f.labels.length >= 2 &&
    f.values.length >= f.labels.length && f.values.slice(0, f.labels.length).every(v => Number.isFinite(Number(v)) && Number(v) >= 0);
  return false;
}

// ---------- assemble ----------
const w = parseJson(wrap) || {};
let fig = w.figure;
if (!validFigure(fig)) {
  fig = { type: 'flow', title: 'Overview', caption: 'The main ideas in this post, in order.', steps: d.sections.map(s => s.heading.split(/\s+/).slice(0, 4).join(' ')).slice(0, 4) };
}
fig.title = String(fig.title || 'Figure').slice(0, 60);
let svg, note = '';
if (fig.type === 'flow') svg = flowSvg(fig);
else if (fig.type === 'function') { svg = fnSvg(fig); note = ' (Conceptual shape; axes are not to scale.)'; }
else { svg = barSvg(fig); note = ' (Illustrative relative values, not measured data.)'; }
const figureHtml = `<figure style="margin:28px 0">${svg}<figcaption style="text-align:center;font-size:14px;color:${C.muted};margin-top:8px">Figure: ${esc(fig.caption || fig.title)}${note}</figcaption></figure>`;

const takeaways = (Array.isArray(w.takeaways) && w.takeaways.length ? w.takeaways : d.sections.map(s => 'Review: ' + s.heading)).slice(0, 4);
const quiz = (Array.isArray(w.quiz) ? w.quiz : []).filter(q => q && q.question && q.answer).slice(0, 3);

const h2 = 'font-size:26px;line-height:1.3;margin:36px 0 12px;color:#0f172a;border-bottom:2px solid #e2e8f0;padding-bottom:6px';
const words = d.sections.reduce((n, s) => n + s.text.split(/\s+/).length, 0) + d.intro.split(/\s+/).length;
const mins = Math.max(2, Math.round(words / 200));

let body = '';
d.sections.forEach((s, i) => {
  body += `<h2 id="s${i + 1}" style="${h2}">${esc(s.heading)}</h2>\n${toHtml(s.text, s.heading)}\n`;
  if (i === 1 || (d.sections.length < 2 && i === 0)) body += figureHtml + '\n';
});

const toc = '<ol style="margin:0;padding-left:22px">' +
  d.sections.map((s, i) => `<li style="margin:3px 0"><a href="#s${i + 1}" style="color:${C.accent}">${esc(s.heading)}</a></li>`).join('') + '</ol>';

const html = `<!-- Generated by n8n with model output. REVIEW FACTS BEFORE PUBLISHING. Sections missing: ${d.sections.filter(s => s.missing).length} -->
<div style="max-width:760px;margin:0 auto;background:#ffffff;color:#1f2937;padding:22px;border-radius:12px;font-family:Georgia,'Times New Roman',serif;font-size:18px;line-height:1.75">
<div style="font-family:${FONT};font-size:14px;background:#eff6ff;border-left:4px solid ${C.accent};padding:10px 14px;border-radius:6px;margin-bottom:20px">
<strong>${esc(d.cat)}</strong> &nbsp;|&nbsp; Level: ${esc(d.level)} &nbsp;|&nbsp; About ${mins} min read</div>
<p style="margin:0 0 16px;font-size:20px"><em>${esc(d.intro)}</em></p>
<!--more-->
<div style="font-family:${FONT};font-size:15px;background:#f8fafc;border:1px solid #e2e8f0;padding:12px 16px;border-radius:8px;margin:20px 0">
<strong>In this post</strong>${toc}</div>
${body}
<h2 style="${h2}">Key takeaways</h2>
<ul style="margin:0 0 16px;padding-left:24px">${takeaways.map(t => `<li style="margin:6px 0">${inline(t)}</li>`).join('')}</ul>
